-- Migracion 046: reescritura de "Uso practico de Bitcoin".
--
-- Aplicada a mano el 24/09/2026 y versionada despues con el SQL exacto.
--
-- QUE CAMBIA
--
--   De 2 modulos y 6 lecciones (8.904 caracteres) a 3 modulos y 9
--   lecciones (54.320). Cierra los dos huecos de la auditoria: no
--   explicaba como se consiguen bitcoins ni mencionaba estafas.
--
-- FRONTERAS
--
--   Con Como funciona Bitcoin: comisiones, confirmaciones, direcciones y
--   el satoshi se APLICAN, no se redefinen. Siete remisiones explicitas.
--   Con Cold Storage: la 3.1 se queda solo con la decision diaria -cuanto
--   tener a mano- y remite el modelo de amenazas y los tres bolsillos,
--   que ya son su leccion 1.1. Seis remisiones.
--   Con el articulo de Coldcard: la 1.1 dice explicitamente que un
--   aparato dedicado NO hace segura la semilla por comprarlo, que es lo
--   que desmintio el incidente de julio de 2026.
--   Con Seguridad basica: la 1.3 cubre los vectores propios de una
--   transaccion y remite alli el catalogo del resto del ecosistema.
--
-- SLUGS
--
--   Los 6 originales se CONSERVAN, reasignados en cascada a la leccion
--   que trata ese tema. Comprobado antes de aplicar que los 3 nuevos no
--   chocaban dentro del curso, y despues que no se perdio ninguno ni hay
--   duplicados. Los slugs de leccion son unicos por curso, no globales.
--
-- Respaldo: C:Usersalberackups-sql&-volver-atras.sql.bak, con
-- las 19 columnas de cada leccion, slug y order_index incluidos (regla 21).

BEGIN;

-- Modulos
INSERT INTO public.modules (id, course_id, title, slug, description, order_index, total_lessons)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', '4aea4d51-c81b-453d-a542-972322903d7c', 'Antes de tu primera transacción', 'antes-de-tu-primera-transaccion', 'En este módulo aprenderás qué necesitas para empezar a usar Bitcoin y cómo realizar las primeras operaciones básicas de forma consciente.

Verás qué es una wallet, cómo enviar y recibir Bitcoin, y qué significan las comisiones y confirmaciones, entendiendo qué ocurre realmente en la red cuando realizas una transacción.

El objetivo es pasar de la teoría a la práctica sin prisas, evitando errores habituales en el primer contacto con Bitcoin.', 0, 3)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, slug = EXCLUDED.slug, total_lessons = 3;

INSERT INTO public.modules (id, course_id, title, slug, description, order_index, total_lessons)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', '4aea4d51-c81b-453d-a542-972322903d7c', 'Tu primera transacción', 'tu-primera-transaccion', 'En este módulo aprenderás cómo usar Bitcoin con criterio en situaciones reales, entendiendo qué decisiones son razonables, qué errores evitar y qué expectativas tener cuando lo utilizas fuera del entorno teórico.

El objetivo es que el alumno no solo sepa usar Bitcoin, sino que sepa cuándo, cómo y para qué tiene sentido usarlo, minimizando riesgos y frustraciones.', 1, 3)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, slug = EXCLUDED.slug, total_lessons = 3;

INSERT INTO public.modules (id, course_id, title, slug, description, order_index, total_lessons)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '4aea4d51-c81b-453d-a542-972322903d7c', 'Usar Bitcoin con criterio', 'usar-bitcoin-con-criterio', 'Modulo del curso Uso practico de Bitcoin.', 2, 3)
