DELETE FROM public.quiz_questions WHERE module_id IN ('7bfe26ac-669f-404d-9171-7b5c7afe0634', '103a5c03-a93b-406d-be87-7873ef2f2668', '9d43e585-8904-4e31-b492-2dd1db60203d');

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', 'Desinstalas tu aplicación de cartera del teléfono por error. ¿Qué ocurre con tus bitcoins?', 'Una cartera no es un recipiente: guarda las claves que permiten gastar unos fondos que están en el registro compartido. Lo que sí es definitivo es lo contrario: tener la aplicación instalada sin haber hecho la copia no garantiza el acceso si pierdes el dispositivo.', '["Se pierden: estaban guardados dentro de la aplicación","Siguen en el registro de la red; con la copia de seguridad los recuperas en cualquier otra cartera","Se devuelven automáticamente a quien te los envió","Quedan bloqueados hasta que reinstales esa misma aplicación"]'::jsonb, 1, 1, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', 'Una cartera te ofrece recuperar el acceso con tu correo y una contraseña. ¿Qué te dice eso?', 'Es la prueba más rápida para responder a la primera de las cuatro preguntas. Si alguien puede devolverte el acceso, es porque lo tiene. Lo que tienes tú es una anotación a tu favor, no la capacidad de cumplir la condición de gasto.', '["Que tiene un sistema de respaldo especialmente bueno","Que usa un estándar distinto de copia de seguridad","Que las claves no son tuyas: las tiene quien puede devolverte el acceso","Que conviene activar además la verificación en dos pasos"]'::jsonb, 2, 2, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', '¿Qué protege exactamente un aparato dedicado a firmar?', 'Las claves no salen del aparato y las transacciones se firman dentro, así que reduce mucha superficie de ataque. Pero la calidad de la generación de la semilla es una pregunta distinta, que no se responde mirando el aparato: se trata en Cold Storage, lección 1.3.', '["Lo que ocurre con tus claves después de generarlas; no cómo se generaron","Todo el ciclo de vida de la semilla, desde que nace","Los fondos frente a un envío a la dirección equivocada","El valor de los bitcoins frente a caídas de precio"]'::jsonb, 0, 3, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', 'Compras bitcoins en una plataforma con custodia y ves el saldo en tu cuenta. ¿Qué tienes exactamente?', 'La operación se completa al retirar a tu propia cartera, que es cuando ocurre una transacción real y pasas a controlar las claves. No es teórico: varias plataformas han suspendido retiros o han quebrado, y el saldo en pantalla era correcto y no servía de nada.', '["Bitcoins en tu poder, igual que si los tuvieras en tu propia cartera","Un derecho de cobro contra esa empresa: las claves las tiene ella","Bitcoins bloqueados que se liberan tras un periodo de seguridad","Una participación en el fondo común de la plataforma"]'::jsonb, 1, 4, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', '¿Cuál de estas cuatro vías para conseguir bitcoins es objetivamente la mejor?', 'Cada vía sale bien parada en un eje y mal en otro, y cuál pesa más depende de tu situación. Cobrar por tu trabajo es la más directa y la menos disponible; los cajeros suelen aplicar comisiones bastante más altas; la plataforma es cómoda y exige identificación completa.', '["El intercambio entre particulares, porque evita la identificación","Cobrar por tu trabajo, porque no hay que comprar nada","La plataforma con custodia, porque es la más cómoda","Ninguna: cada una intercambia identificación, confianza, coste y comodidad de forma distinta"]'::jsonb, 3, 5, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', '¿Qué consecuencia práctica tiene identificarte en una plataforma antes de retirar?', 'Es el punto de anclaje que convierte el seudónimo en algo rastreable: desde esa dirección se puede seguir lo que ocurra después. No es alarmante, es así, y conviene saberlo antes que después. Cómo se gestiona en el día a día es la lección 3.2.', '["Que tu identidad queda asociada a esa dirección, y la cadena es pública y permanente","Que tus transacciones futuras pasan a ser privadas","Que la plataforma responde de los fondos una vez retirados","Que quedas exento de obligaciones fiscales en ese país"]'::jsonb, 0, 6, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', '¿Por qué las estafas resultan más rentables con Bitcoin que con una tarjeta?', 'El primer intento que funciona es definitivo. De ahí salen dos consecuencias: compensa invertir esfuerzo en un solo objetivo, y compensa esperar al momento exacto en que vas a mover fondos y estás concentrado en otra cosa.', '["Porque las direcciones son difíciles de rastrear","Porque una transacción confirmada no se deshace: no hay reclamación ni reversión","Porque las comisiones bajas abaratan el ataque","Porque la mayoría de usuarios no usa contraseñas"]'::jsonb, 1, 7, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', 'Publicas una duda en un servidor de Discord y a los minutos te escribe por privado alguien ofreciéndose a ayudarte. ¿Qué haces?', 'Llega cuando estás atascado y agradecido de que alguien conteste, y la conversación es útil un rato antes de pedirte compartir pantalla, introducir tu frase en una web de "validación" o hacer un envío de prueba. Nodo360 no te escribirá nunca por mensaje directo primero.', '["Aceptar si se identifica como soporte del proyecto","Aceptar solo si no te pide la frase de recuperación","Desconfiar: la ayuda legítima ocurre en público, donde otros pueden corregirla","Compartir pantalla para que vea el problema más rápido"]'::jsonb, 2, 8, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7bfe26ac-669f-404d-9171-7b5c7afe0634', 'Vas a repetir un envío y tomas la dirección de una transacción anterior de tu historial. ¿Qué riesgo corres?', 'El atacante te envía una cantidad mínima desde una dirección con los mismos primeros y últimos caracteres, contando con que reutilices lo que ya funcionó. Nunca saques una dirección del historial: pídela otra vez a quien vas a pagar, o genérala de nuevo si es tuya.', '["Ninguno: si ya funcionó una vez, la dirección es correcta","Que la dirección haya caducado y el envío falle","Que la cartera cobre una comisión más alta por reutilizarla","Que sea una dirección envenenada, sembrada ahí a propósito para parecerse a la tuya"]'::jsonb, 3, 9, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', 'Antes de firmar un envío, ¿qué comprobación no puede sustituirse por ninguna otra?', 'Entera, no los cuatro primeros caracteres: las direcciones de estos ataques empiezan igual a propósito. Es lo que desactiva tanto el portapapeles cambiado como las direcciones envenenadas. Con un aparato dedicado, la dirección que vale es la de su pantalla.', '["Que la comisión esté dentro de lo razonable","La dirección entera, después de pegarla","Que haya saldo suficiente para cubrir la comisión","Que la cartera esté actualizada a la última versión"]'::jsonb, 1, 1, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', '¿Para qué sirve el envío de prueba antes de mover una cantidad importante?', 'Pagas una comisión de más y a cambio descubres, cuando todavía no importa, que te habías equivocado de dirección, que la cartera del otro no era la que creías o que habías confundido la unidad. Vale para cualquier destino nuevo.', '["Para que la red registre tu dirección como fiable","Para reducir la comisión total de las dos operaciones","Para descubrir un error cuando todavía no importa","Para acelerar la confirmación de la transacción grande"]'::jsonb, 2, 2, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', 'Alguien te dice que ya te ha pagado y te manda una captura de su cartera. ¿Qué haces?', 'El registro es público: pegas el identificador y ves si está esperando, en qué bloque entró y cuántas confirmaciones lleva, sin preguntarle a nadie. Un explorador solo lee y nunca pide tus claves, aunque conviene saber que deja rastro de lo que consultas.', '["Aceptarla: la captura muestra la transacción firmada","Comprobarlo tú en un explorador de bloques; una captura no prueba nada","Pedirle que te reenvíe el pago para asegurarte","Esperar a que te lo confirme tu propia plataforma"]'::jsonb, 1, 3, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', '¿Con qué criterio conviene elegir la comisión de un envío?', 'La comisión paga espacio, no cantidad. Si alguien espera delante, paga la rápida; si mueves fondos entre carteras tuyas, la lenta basta. Y las estimaciones de tiempo son estimaciones: si entra una avalancha después de que firmes, la tuya espera.', '["Según la cantidad que estás enviando","Según qué pasa si tarda: quién está esperando al otro lado","Siempre la más alta, para asegurar la confirmación","Según el saldo total que tengas en la cartera"]'::jsonb, 1, 4, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', 'Tu transacción lleva horas sin confirmarse. ¿Cuál es el primer error que hay que evitar?', 'La primera sigue viva, y enviar otra con los mismos fondos acaba en confusión sobre cuál salió. Casi nunca hace falta actuar: cuando la red se vacía entra sola. Si hay prisa, se puede sustituir por otra con más comisión o dejar que la empuje quien cobra, pero eso acelera, no cancela.', '["Volver a enviar el pago","Consultarla en un explorador","Esperar sin hacer nada","Avisar a quien tiene que cobrar"]'::jsonb, 0, 5, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', 'Has recibido treinta pagos pequeños y quieres gastarlos todos juntos. ¿Qué esperas?', 'Recibir muchas cantidades diminutas crea un gasto futuro: cada una es barata de recibir y cara de mover. Si acumulas muchas, conviene juntarlas un día que la red esté tranquila, no el día que tengas prisa. Es también por lo que a veces no puedes enviar todo tu saldo.', '["Una comisión normal: depende de la cantidad, no del número de cobros","Una comisión más alta, porque cada cobro hay que incluirlo y firmarlo por separado","Que la cartera los agrupe automáticamente sin coste","Que la red rechace la transacción por tener demasiadas entradas"]'::jsonb, 1, 6, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', 'El dígito de control que llevan las direcciones, ¿de qué protege?', 'Si cambias un carácter, lo más probable es que la cartera avise de que no es válida. Pero la dirección de otra persona es perfectamente válida: el control no puede saber que no era la que querías. Por eso la comprobación visual sigue siendo necesaria.', '["De que envíes a la dirección de otra persona","De que la cartera use la red equivocada","De las erratas al copiar, no de copiar la dirección equivocada","De que alguien intercepte la transacción"]'::jsonb, 2, 7, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', '¿Por qué la mayoría de los errores caros no son técnicos?', 'Quien envía a la dirección equivocada suele saber perfectamente que hay que comprobarla; esa vez no lo hizo. Por eso la defensa son costumbres y no conocimientos: una costumbre funciona cuando estás cansado o distraído, que es cuando falla el conocimiento.', '["Porque las carteras actuales son demasiado complicadas","Porque casi nadie entiende cómo funcionan las transacciones","Porque el protocolo tiene fallos que aún no se han corregido","Porque son hacer con prisa algo que se sabe hacer despacio"]'::jsonb, 3, 8, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('103a5c03-a93b-406d-be87-7873ef2f2668', 'Alguien te mete prisa para que hagas un pago ya. ¿Cómo hay que leer eso?', 'La urgencia es parte del método, no una casualidad: nadie comprueba bien una dirección mientras le meten prisa. Ninguna operación legítima se estropea por esperar cinco minutos, y quien diga lo contrario te está dando información sobre sí mismo.', '["Como una señal de alarma, no como un contexto","Como algo normal en operaciones entre particulares","Como un motivo para elegir una comisión más alta","Como una razón para saltarse el envío de prueba"]'::jsonb, 0, 9, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿Cuánto conviene tener en la cartera de uso diario?', 'Es la misma cantidad que llevarías en efectivo en el bolsillo, y se reconoce preguntándose si perderla sería un disgusto o una molestia. Una sola cartera para todo le pide dos trabajos incompatibles: estar disponible al instante y proteger lo que no tocas.', '["Un porcentaje fijo del total, revisado cada mes","Lo mínimo imprescindible para una sola operación","Una cantidad que pudieras perder sin que te cambie la semana","Todo, siempre que la cartera tenga contraseña"]'::jsonb, 2, 1, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿De qué protege principalmente separar lo que gastas de lo que guardas?', 'Separar no reduce la probabilidad de equivocarse: reduce cuánto cuesta cada equivocación. Y como equivocarse es seguro y ser atacado no, es la protección que más veces sirve. La otra práctica que basta es reponer en vez de vaciar.', '["De los ataques dirigidos, que son el riesgo más frecuente","De que un error tuyo tenga consecuencias limitadas","De las caídas de precio a corto plazo","De que la cartera deje de recibir actualizaciones"]'::jsonb, 1, 2, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', 'Llevas meses con un saldo en la plataforma donde compraste, sin haberlo decidido. ¿Cuál es la pregunta útil?', 'Dejar algo ahí tiene sentido para un uso concreto y a corto plazo. Lo que no lo tiene es que se quede meses porque nunca hubo un momento para moverlo: es la forma más habitual de acabar con un saldo importante en manos de un tercero sin haberlo elegido.', '["¿Está la plataforma regulada en mi país?","¿Ha subido o bajado desde que lo dejé ahí?","¿Tiene la plataforma verificación en dos pasos activada?","¿Está aquí por una razón, o porque no lo he movido?"]'::jsonb, 3, 3, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿Qué consigues usando una dirección nueva en cada cobro?', 'Si cobras siempre en la misma, cualquiera que la conozca —alguien a quien le cobraste hace dos años— puede consultar cuánto has recibido desde entonces. No te vuelve invisible, porque al gastar varias direcciones pueden aparecer juntas, pero evita el error más básico. Y no da trabajo: solo hay que no impedirlo.', '["Que tus transacciones dejen de ser públicas","Que no haya un único sitio visible donde se acumule todo lo que recibes","Que nadie pueda relacionar entre sí ninguna de tus direcciones","Que las comisiones de tus envíos sean más bajas"]'::jsonb, 1, 4, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', 'Una web te pide tu clave pública extendida (xpub) para mostrarte el saldo. ¿Qué implica dársela?', 'Es cierto que con ella no se puede gastar, y eso es lo único que suele decirse. Lo otro es que de ella se derivan todas tus direcciones: no una, el conjunto. Es un problema de privacidad serio aunque no sea uno de custodia. Trátala como información sensible.', '["Nada: con la xpub no se puede gastar","Que podrían gastar tus fondos si además conocen una dirección","Que quien la tenga ve todo tu historial y tu saldo, presente y futuro","Que tus direcciones dejarían de generarse correctamente"]'::jsonb, 2, 5, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿En qué consiste la privacidad en Bitcoin, realistamente?', 'Ocultarlas no se puede: el registro es público y permanente, y un pago de hoy será igual de consultable dentro de veinte años. Para el uso normal bastan tres costumbres: no reutilizar direcciones, no publicar las tuyas y no repartir la xpub.', '["En ocultar las transacciones para que no se puedan consultar","En borrar del registro las operaciones antiguas","En usar siempre la misma dirección para no dispersar la información","En no facilitar las conexiones entre transacciones; es cuestión de grado"]'::jsonb, 3, 6, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿Cuál es la contrapartida directa de que nadie pueda bloquear tus fondos?', 'La misma ausencia de autoridad sirve para las dos cosas: no hay quien te bloquee y no hay quien te rescate. De ahí salen las demás contrapartidas: la responsabilidad entera es tuya, y nadie te avisará si dejas de hacer las comprobaciones.', '["Que las comisiones sean más altas que en el sistema bancario","Que tampoco haya quien deshaga un error tuyo","Que las transacciones tarden más en confirmarse","Que necesites identificarte para operar"]'::jsonb, 1, 7, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿Qué puede decir este curso sobre lo que valdrá un bitcoin en el futuro?', 'Lo comprobable son las reglas: cuántos bitcoins existen, cuántos habrá y a qué ritmo. El precio no. Quien afirme lo contrario está vendiendo algo, aunque lo diga con gráficos y vocabulario técnico. Ante cualquier afirmación: ¿esto se comprueba, o hay que creérselo?', '["Que subirá a largo plazo por la emisión limitada","Que es imposible saberlo: depende del comportamiento futuro de millones de personas","Que se mantendrá estable una vez se extienda la adopción","Que bajará hasta que se resuelvan los problemas de escalabilidad"]'::jsonb, 1, 8, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9d43e585-8904-4e31-b492-2dd1db60203d', '¿Cuál de estas NO es una de las cinco señales de alarma con las que cierra el curso?', 'Que una transacción tarde es normal y depende de la comisión y del estado de la red. Las cinco señales son: rentabilidad prometida, quien pida tus palabras de recuperación, la urgencia, el mensaje privado no solicitado y los recuperadores de fondos.', '["Que una transacción tarde varias horas en confirmarse","Que alguien prometa o garantice una rentabilidad","Que te escriban primero por privado ofreciendo ayuda","Que te ofrezcan recuperar fondos enviados o semillas perdidas"]'::jsonb, 0, 9, 'medium', 1);

